> > >     p32(c, 1);   /* max_buckets */
> > >     p32(c, 1);   /* max_rules */
> > >     p32(c, 4);   /* max_devices */
> > >     /* bucket[0] */
> > >     p32(c, CRUSH_BUCKET_STRAW2); /* alg (outer) */
> > >     p32(c, (uint32_t)-1);        /* id = -1 */
> > >     p16(c, 1);                   /* type */
> > >     p8(c, CRUSH_BUCKET_STRAW2);  /* alg (inner, must match) */
> > >     p8(c, 0);                    /* hash */
> > >     p32(c, 0x10000);             /* weight */
> > >     p32(c, 4);                   /* size */
> > >     p32(c, 0); p32(c, 1); p32(c, 2); p32(c, 3); /* items */
