> > >     /* rule[0] */
> > >     p32(c, 1);   /* present */
> > >     p32(c, 3);   /* len = 3 steps */
> > >     /* mask: ruleset=0,type=1,min_size=1,max_size=10 */
> > >     p8(c,0); p8(c,1); p8(c,1); p8(c,10);
